param([switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'resolve-enterprise-powershell.ps1');$runtime=Get-EnterprisePowerShellCommand;$stamp=(Get-Date).ToString('yyyyMMddHHmmssfff');$script=Join-Path $PSScriptRoot 'new-enterprise-product-experiment.ps1';$path=Join-Path $projectRoot ".qianlima/run-traces/enterprise-product-experiments/experiment-$stamp.json"
function Invoke-Case([string[]]$Arguments){$raw=@(& $runtime -NoProfile -File $script @Arguments 2>&1);[pscustomobject]@{code=$LASTEXITCODE;text=(($raw|ForEach-Object{$_.ToString()})-join"`n")}}
$base=@('-ExperimentId',"experiment-$stamp",'-SubjectType','agent','-TargetRole','enterprise-security-admin','-RealScenario','Connect one external read-only research Agent without exposing raw internal data.','-CurrentExperience','Manual research with incomplete traceability.','-ExpectedExperience','Grant-bound read-only research with evidence and revocation.','-CoreUserValue','Faster research without losing enterprise control.','-MigrationCosts','admin_training;approval_load','-SupplyCapabilities','identity;policy;data_guard;approval;evidence;audit;revocation_or_rollback','-Hypothesis','A sanitized read-only Agent can complete research with complete audit lineage.','-BoundedScope','one tenant, one project, public and sanitized references only','-Baseline','manual research workflow','-SuccessMetrics','task_completion_rate;audit_completeness','-FailureMetrics','unexpected_data_exposure;missing_audit_event','-StopConditions','any_unexpected_data_exposure;audit_incomplete','-RollbackRef','rollback://disable-agent-card','-MaxCostUnits','100','-MaxDurationHours','168','-OwnerId','product-owner','-IndependentEvaluatorId','security-evaluator','-OutputPath',$path,'-PassThru')
$cases=[System.Collections.Generic.List[object]]::new();$ok=Invoke-Case $base;$cases.Add([pscustomobject]@{name='bounded_candidate_is_created';passed=($ok.code-eq0-and$ok.text-match'"execution_authorized"\s*:\s*false'-and$ok.text-match'"permission_expansion"\s*:\s*false')});$hash=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash;$duplicate=Invoke-Case $base;$cases.Add([pscustomobject]@{name='experiment_definition_is_immutable';passed=($duplicate.code-ne0-and$duplicate.text-match'experiment_already_exists'-and(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash-eq$hash)});$same=@($base);$same[([array]::IndexOf($same,'security-evaluator'))]='product-owner';$blocked=Invoke-Case $same;$cases.Add([pscustomobject]@{name='independent_evaluation_is_required';passed=($blocked.code-ne0-and$blocked.text-match'independent_evaluator_must_differ_from_owner')});$missing=@($base);$supplyIndex=[array]::IndexOf($missing,'identity;policy;data_guard;approval;evidence;audit;revocation_or_rollback');$missing[$supplyIndex]='identity;policy;data_guard;approval;evidence;audit';$supplyBlocked=Invoke-Case $missing;$cases.Add([pscustomobject]@{name='stable_supply_is_required_before_experiment';passed=($supplyBlocked.code-ne0-and$supplyBlocked.text-match'stable_supply_capability_missing')});$failed=@($cases|Where-Object{-not$_.passed});$result=[pscustomobject]@{passed=($failed.Count-eq0);cases=@($cases);external_calls=$false;listeners_opened=$false;business_write=$false;permission_expansion=$false};if($PassThru){$result|ConvertTo-Json -Depth 10}else{$cases|Format-Table -AutoSize};if($failed.Count){throw('Enterprise product validation regression failed: '+(($failed.name)-join', '))}
